sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.quick-actions-section {
  width: 100%;
  padding: 90px 8%;
  background: #1F1F1F;
  font-family: Arial, sans-serif;
}

.section-heading {
  text-align: center;
  margin-bottom: 50px;
}

.section-tag {
  color: #53BA00;
  font-size: 12px;
  font-weight: bold;
  letter-spacing: 1.5px;
}

.section-heading h2 {
  margin: 12px 0;
  color: #FFFFFF;
  font-size: 36px;
  font-weight: 700;
}

.section-heading p {
  max-width: 600px;
  margin: 0 auto;
  color: #B0B0B0;
  font-size: 16px;
  line-height: 1.6;
}

.quick-actions {
  display: flex;
  gap: 25px;
  max-width: 1150px;
  margin: auto;
}

.action-card {
  flex: 1;
  padding: 35px 28px;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  background: #1F1F1F;
  text-align: center;
  transition: 0.3s;
}

.action-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 25px rgba(0,0,0,0.08);
}

.action-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: rgba(83,186,0,0.1);
  color: #53BA00;
  font-size: 24px;
}

.action-card h3 {
  margin: 0 0 12px;
  color: #FFFFFF;
  font-size: 20px;
}

.action-card p {
  min-height: 48px;
  color: #B0B0B0;
  font-size: 14px;
  line-height: 1.6;
}

.action-card a {
  color: #53BA00;
  font-weight: bold;
  text-decoration: none;
  font-size: 14px;
}

.featured {
  border: 2px solid #2563eb;
}

@media (max-width: 768px) {
  .quick-actions {
    flex-direction: column;
  }

  .section-heading h2 {
    font-size: 30px;
  }
}
